from l09_lessons import render,GLOSSARY,REFERENCES

LESSONS=[
 ('Exact intake','D','Observe raw identity, UTC and exact cents; distinguish a transport receipt from business value.','Compare North E1 and South E1. Explain why1.005 USD is not a whole-cent transaction.','Read a two-row worked example, use the field glossary, inspect four typed rejects; do not cast float then round.','Explain a canonical wire normalization and generate a valid new tenant/amount control without changing meaning.'),
 ('Relational current state','S','Execute a joint-key MAX/join or DENSE_RANK SQL query; prove latest-state rather than latest-valid reasoning.','State what happens when revision2 is missing or cancelled and revision1 was active.','Run the supplied join in fragments, inspect each relation and trace O3 to its selected sources.','Implement the equivalent window formulation; compare complete states/lineage, not SQL spelling.'),
 ('Commit, lost ACK and replay','R','Keep original journal and same request receipt through real committed-write exit73; inspect the database before retry.','A process exits after commit. Is a fresh request or deleting the database justified?','Keep the state path unchanged; inspect committed.json/checkpoint; retry exactly W3; compare original receipt and journal.','Explain the transaction boundary and why a checkpoint plus receipt supports process restart but does not certify power-loss behavior.'),
 ('Late records and incidents','D/S/R','Retain late older arrivals, quarantine source conflicts, interpret future eligibility and later unique corrections.','Track O4 conflicting revision2 and East O8 wire conflict without inventing a known amount.','Use W3 checkpoint in a new state, list changes with source IDs and compare before/current snapshots.','Build a reconciliation query over original journal/current state; explain unknown versus known zero and blocked upstream claims.'),
 ('Principal scope and audit','A','Query own tenant, cross tenant, unknown identity and admin; log decisions from the principal policy.','Why does request.tenant=South not authorize north_reader?','Use the role table, predict each request then run it, inspect denied output and durable audit.','Add a new tenant reader and prove allowed/denied sets follow policy rather than hardcoded tenant names.'),
 ('Evidence and transferable handover','D/S/R/A','Run the complete corrected chain and restore a later lesson from original intermediate evidence; grade behavior and separate human outcomes.','A script and grader passed. What is and is not known about human learning or production security?','Use the clean-run checklist, exact table companion and replay-safe checkpoint commands; explain a failed criterion from its source.','Audit a correct alternative SQL answer and unfamiliar defects; propose a real human study without claiming it has occurred.')]
def deliver(source,evidence,out,weak=False):
 out.mkdir(parents=True,exist_ok=False);(out/'student-pack').mkdir();(out/'teacher-pack').mkdir();c=load(source/'course-contract.json');diagnostics=load(source/'diagnostics.json');sessions=[]
 shutil.copytree(evidence,out/'evidence');shutil.copytree(source,out/'source-archive')
 programme=Path(__file__).resolve().parent;declaration=load(programme/'submission.json');answers=out/'teacher-pack/source';answers.mkdir()
 for name in declaration['files']:
  target=answers/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes((programme/name).read_bytes())
 save(answers/'submission.json',declaration)
 (out/'GLOSSARY.md').write_text(GLOSSARY,encoding='utf-8');(out/'REFERENCES.md').write_text(REFERENCES,encoding='utf-8')
 for kind,command in [('packets',[sys.executable,str(programme/'l09_packets.py'),'--source',str(source),'--out',str(out/'packets')]),('worked',[sys.executable,str(programme/'l09_worked.py'),'--out',str(out/'worked')])]:
  p=subprocess.run(command,capture_output=True,text=True);save(out/(kind+'-native.json'),{'argv':command,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr})
  if p.returncode:raise ValueError(kind+'_actual_helper_failed')
 for i,(title,domain,goal,question,guided,challenge) in enumerate(LESSONS,1):
  sessions.append({'id':'W'+str(i),'hours':5,'lab_id':i,'objectives':[goal],'prerequisites':[] if i==1 else ['W'+str(i-1)],'domains':domain.split('/')})
  observed=load(evidence/'guided'/f'lab{i}'/'lab.json');native=load(evidence/'guided'/f'lab{i}'/'actual-native.json')
  manual,teacher=render(i,observed,native)
  (out/'student-pack'/f'week{i}.md').write_text(manual,encoding='utf-8')
  (out/'teacher-pack'/f'week{i}-answers.md').write_text(teacher,encoding='utf-8')
 diagnoses=[{'learner_id':x['learner_id'],'observed_task':x['observed_task'],'observed_counterexample':x['observed_counterexample'],'route_recommendation':'guided worked-example plus evidence retrieval' if x['prior_experience']=='spreadsheet user' else 'challenge SQL/transaction audit with same core objective','rationale':'Constructed response '+x['submitted_fragment']+' is the local evidence; honor '+x['support_need']+'. It does not establish a stable deficit or learning gain.'} for x in diagnostics]
 save(out/'course.json',{'sessions':sessions,'diagnostics':diagnoses,'source_scope':'24 original fictional records; no real human outcomes','total_learner_hours':30})
 forms=[]
 for form,names,amount in [('pre',['P-N','P-S'],1250),('post',['Q-E','Q-W'],2375)]:
  forms.append({'id':form,'items':[{'domain':'D','prompt':f'{names}: same order name across two tenants; amounts {amount}/100 USD and1.005 USD. Give joint identity and exact-cent admissibility.','answer':'tenant/order are joint; first amount has exact cents,1.005 fails amount_grid; no rounding to force admission.'},{'domain':'S','prompt':f'{names}: revision1 active {amount}; revision2 missing. Another order revision2 cancelled0. What is current and why?','answer':'Select revision first: missing/null held vs cancelled/0 known; neither resurrects revision1.'},{'domain':'R','prompt':f'{names}: W3 committed journal and receipt before process exit; sender saw no ACK. Which request/state is retried?','answer':'Keep original state and request ID; durable original receipt and idempotent rows survive; no delete or new key.'},{'domain':'A','prompt':f'An own-tenant reader requests the other {names} tenant; unknown principal requests all. State results and audit requirement.','answer':'Both denied/permission_denied with empty data; retain principal/request/decision audit; admin separate.'}],'anchors':{'2':'Correct mechanism and complete boundary applied to the changed example with evidence.','1':'Correct principal result but incomplete mechanism or one required boundary.','0':'Wrong key/state/transaction/authority, missing response or unsupported guarantee.'},'limits':'Same construct/structure and changed surface identities/amount; no empirical difficulty equating or learning-effect evidence.'})
 save(out/'assessment-forms.json',{'forms':forms,'concept_points':8,'functional_points':20,'separation':'Functional behavior is not a proxy for conceptual explanation or human learning.'})
 handover=out/'handover';handover.mkdir();seed=evidence/'guided/lab3-commit-exit/checkpoint.json';shutil.copy2(seed,handover/'checkpoint.json');packet(source,4,handover/'packet4');shutil.copytree(evidence/'guided/lab3-commit-exit',handover/'origin-w3-commit')
 (out/'TEACHER-HANDOVER.md').write_text('''# Replacement teacher

Use the declared public offline dependency environment. The actual declared frozen source/argv and public contract assets are included under teacher-pack/source; original raw archive is source-archive; original results/SQL/sanitized native receipts are evidence/guided and evidence/challenge. Set the working directory to teacher-pack/source for the declared argv. Start a new empty state and run packet1,2; run packet3 once with --crash-after-commit expecting73, retain state and replay packet3 without it expecting0; continue4,5,6. Always use a new output directory, never delete the state/receipts to repair a failed assertion. Both guided and challenge are legitimate SQL routes.

Independent later lesson: let ROOT be the absolute unpacked delivery directory; use ROOT/handover/packet4 and actual ROOT/handover/checkpoint.json from the committed W3. From ROOT/teacher-pack/source, call the declared lab entry --data ROOT/handover/packet4 --state <newstate> --out <newout> --route guided --restore ROOT/handover/checkpoint.json. Compare every snapshot/receipt/journal to ROOT/evidence/guided/lab4/{lab,checkpoint}.json, including held rows and typed errors. The seed is a logical schema1 checkpoint with original admitted rows/receipts, not only a final database. handover/origin-w3-commit retains source/clock/request/native context and actual unacknowledged committed receipt. Original event packets can be regenerated with the included l09_protocol.packet helper against ROOT/source-archive without access to the evaluator or private grading key.

For each week use the student handout and corresponding teacher answer; pre/post forms have separate2/1/0 conceptual anchors. The fixed20 functional criteria can award partial marks by observed domain; a different correct SQL style earns the same marks. Unfamiliar work remains source-bound; do not grade by filename or student self-score. Technical failure is an execution observation, not a cognitive diagnosis.

The public source contract is the numerical authority. Exact CSV/table companions support figures and keyboard-only instructions. Escalate genuine wrong/lost state with original raw/receipts before changing materials. No real accounts, students or provider keys are needed; production security, accessibility certification and human learning effects remain untested.
''',encoding='utf-8')
 grades={p.name.removesuffix('-grade.json'):load(p) for p in evidence.glob('*-grade.json')};save(out/'functional-work.json',grades)
 with (out/'functional-work.csv').open('w',encoding='utf-8',newline='') as f:
  w=csv.writer(f);w.writerow(['constructed_work','D','S','R','A','total'])
  for name,g in grades.items():w.writerow([name,*[g['domains'][d] for d in ('D','S','R','A')],g['total']])
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,2,figsize=(12,5));categories=sorted({x['observed_task'] for x in diagnostics});counts=[sum(x['observed_task']==k for x in diagnostics) for k in categories];axes[0].barh(categories,counts);axes[0].set_xlabel('Constructed observed responses (not mastery)');axes[0].set_title('Diagnostic evidence categories')
 for i,d in enumerate(('D','S','R','A')):axes[1].bar([n for n in grades],[g['domains'][d] for g in grades.values()],bottom=[sum(g['domains'][k] for k in ('D','S','R','A')[:i]) for g in grades.values()],label=d)
 axes[1].set_ylabel('Functional coursework points (0–20)');axes[1].set_title('Actual unfamiliar-program behavior, not human gain');axes[1].legend();fig.tight_layout();fig.savefig(out/'course-evidence.png',dpi=140);plt.close(fig)
 report=['# Course construction and actual rehearsal','All24 learner profiles and unfamiliar programs are original synthetic material. The observed execution and marks do not prove human learning improvement, statistical validity, production security or accessible compliance.30h is learner schedule allocation, not runtime or agent effort.','Six experiments consume actual preceding state; two distinct executed SQL routes reach the same business contract. The committed-write native73 and original-request retry are retained. The separate W4 restore consumes actual W3 checkpoint, source packet and original receipt; it does not reset history.','The counterexample rehearsal intentionally executes wrong programs (sum revisions, global order identity, valid-first selection, state reset after lost ACK, cross-tenant access) and correct alternate SQL. Functional grading preserves partial domain evidence. Teacher answers and complete machine states bind each numerical claim to original row IDs and native outputs.','## Material revision','The supplied initial-teaching-note.md v1 explicitly suggested recreating state after an unacknowledged commit. The constructed reset-on-retry program is an explicit controlled rehearsal of that unsafe step, not a human trial. Its actual outputs/grade are retained. The revised W3 handout now says retain state/request, inspect committed receipt, use new output and replay the same key; the correct actual chain and independent restore passed. No invented measured learner response or learning gain is claimed.','## Sources and operating limits','Read BUSINESS/EXECUTION/GRADING as the fixed task. Per-week answer artifacts, receipts and SQL explain behavior; figures have functional-work.csv/table companions. Missing values remain unknown, not zero; cancelled and withheld are distinct. An unfamiliar correct implementation is accepted on evidence, and unsupported blanket success is rejected even if tables are correct.','## Actual grading summary',str({n:g['domains'] for n,g in grades.items()}),'## Teacher use','The six student handouts, six answer files, assessment-forms.json, course.json and TEACHER-HANDOVER.md are an indexed complete product. Diagnostic recommendations cite only the supplied response and requested supports. Timings are design allocations; the appropriate next step for a genuine learning-effect claim is an authorized human study, not reinterpreting this scripted run.']
 if weak:report+=['## Claimed educational result','Twenty-four real learners completed this course and gained exactly30% mastery; these scripted marks statistically prove the course works for future human cohorts.']
 (out/'REPORT.md').write_text('\n\n'.join(report),encoding='utf-8')
 save(out/'delivery-index.json',{'course':'course.json','report':'REPORT.md','forms':'assessment-forms.json','handover_checkpoint':'handover/checkpoint.json','handover_packet':'handover/packet4','handover_instructions':'TEACHER-HANDOVER.md','student_pack':[f'student-pack/week{i}.md' for i in range(1,7)],'teacher_pack':[f'teacher-pack/week{i}-answers.md' for i in range(1,7)],'functional_grades':'functional-work.json','figures':['course-evidence.png'],'figure_data':['functional-work.csv'],'answer_programme':'teacher-pack/source/submission.json','source_archive':'source-archive','evidence':'evidence'})
def main():
 p=argparse.ArgumentParser();p.add_argument('--source',required=True,type=Path);p.add_argument('--evidence',required=True,type=Path);p.add_argument('--out',required=True,type=Path);p.add_argument('--weak',action='store_true');a=p.parse_args();deliver(a.source,a.evidence,a.out,a.weak)
